import pytest

from pytmc import parser, pragmas
from pytmc.bin import stcmd, template

from .conftest import get_real_motor_symbols


def test_motion_stcmd(capsys, project_filename):
    """
    Sanity check of motor setup in the st.cmd files

    For all plc projects:
        1. Is a controller created only when needed?
        2. Are the right number of axes created?

    Note: capsys is a built-in pytest fixture for capturing stdout and stderr
    """
    controller_func = "EthercatMCCreateController"
    motor_func = "EthercatMCCreateAxis"

    full_project = parser.parse(project_filename)

    for plc_name, plc_project in full_project.plcs_by_name.items():
        motors = get_real_motor_symbols(plc_project)
        # Clear captured buffer just in case
        capsys.readouterr()
        stcmd.main(
            project_filename, plc_name=plc_name, only_motor=True, allow_errors=True
        )
        output = capsys.readouterr().out

        if motors:
            assert controller_func in output
        else:
            assert controller_func not in output

        assert output.count(motor_func) == len(motors)


def test_axis_name_without_pragma():
    from .test_xml_collector import make_mock_twincatitem, make_mock_type

    axis = make_mock_twincatitem(
        name="Main.my_axis",
        data_type=make_mock_type("ST_MotionStage", is_complex_type=True),
        # pragma='pv: OUTER',
    )

    class NCAxis:
        name = "Axis 1"

    axis.nc_axis = NCAxis
    user_config = dict(delim=":", prefix="PREFIX")
    prefix, name = stcmd.get_name(axis, user_config=user_config)
    assert name == NCAxis.name.replace(" ", user_config["delim"])
    assert prefix == user_config["prefix"] + user_config["delim"]


def test_axis_name_with_pragma():
    from .test_xml_collector import make_mock_twincatitem, make_mock_type

    axis = make_mock_twincatitem(
        name="Main.my_axis",
        data_type=make_mock_type("ST_MotionStage", is_complex_type=True),
        pragma="pv: MY:STAGE",
    )

    # axis.nc_axis is unimportant here as we have the pragma
    user_config = dict(delim=":", prefix="PREFIX")
    prefix, name = stcmd.get_name(axis, user_config=user_config)
    assert (prefix, name) == ("MY:", "STAGE")


def test_mixed_motionstage_naming():
    """
    Check an example tmc file with 9 ST_MotionStage and 1 DUT_MotionStage

    We are expecting 10 motor symbols
    If only 9: we only recognize ST_MotionStage
    If only 1: we only recognize DUT_MotionStage
    """
    file = Path(__file__).parent / 'tmc_files' / 'tc_mot_example.tmc'
    tmc_item = parser.parse(file)
    motors = tmc_item.find(parser.Symbol_ST_MotionStage)
    assert len(list(motors)) == 10


def test_macro_in_motor_stcmd():
    """
    Make sure the @ -> $ substitutions happen in stcmd.

    The example TMC has some @(PREFIX) substitutions on motors as well as some
    motors with no @ substitutions.
    """
    file = Path(__file__).parent / 'tmc_files' / 'tc_mot_example.tmc'
    tmc_item = parser.parse(file)
    all_motors = list(tmc_item.find(parser.Symbol_ST_MotionStage))
    yes_sub = [
        motor for motor in all_motors if "@" in next(parser.get_pragma(motor))
    ]
    assert len(yes_sub) > 0, "No motors found that need subs"
    assert len(all_motors) > len(yes_sub), "No motors found that don't need subs"
    user_config = dict(delim=":", prefix="")
    for motor in all_motors:
        prefix, name = stcmd.get_name(obj=motor, user_config=user_config)
        if motor in yes_sub:
            # All the subs here are supposed to drop in the PREFIX
            assert "$(PREFIX)" in prefix
        else:
            # Make sure the non-subs don't get distorted
            assert prefix + name in next(parser.get_pragma(motor))
            # Make sure we didn't miscategorize a yes_sub
            assert "$(PREFIX)" not in prefix + name
        assert "@" not in prefix
        assert "@" not in name


@pytest.fixture(scope="module")
def real_tmc(tmc_motion_abstraction):
    """Parse the motion-abstraction TMC once per module."""
    if not tmc_motion_abstraction.exists():
        pytest.skip(f"TMC fixture not found: {tmc_motion_abstraction}")
    return parser.parse(tmc_motion_abstraction)


def test_real_tmc_scalar_no_axis_link_override(real_tmc):
    """Scalar FB_MotionStage symbols never carry an axis_link_override.

    The override mechanism is array-element only; any scalar
    FB_MotionStageNC instance present in the TMC (e.g. ``fbDummy``)
    must keep ``axis_link_override`` as None so the production
    ``get_axis_link()`` path falls back to the legacy resolver.
    """
    scalars = [
        sym for sym in real_tmc.find(parser.Symbol_FB_MotionStage)
        if not getattr(sym, "array_info", None)
    ]
    if not scalars:
        pytest.skip("TMC fixture exports no scalar FB_MotionStage symbols")

    for sym in scalars:
        assert sym.__dict__.get("axis_link_override") is None, (
            f"Scalar {sym.name} unexpectedly has axis_link_override"
        )


# Matches one or more bracket-indexed groups in a tcname segment.
# `afbMotorsNC[1]` -> ['1']
# `astPositionState[1][2]` -> ['1', '2']
_BRACKET_INDEX_RE = re.compile(r"\[(\d+)\]")


def _extract_indices_for_segment(tcname, segment_name):
    """Extract bracket indices from the tcname segment matching segment_name.

    Returns a tuple of ints (outer, inner, ...) or () if no indices.
    Raises ValueError if the segment isn't found.
    """
    for part in tcname.split("."):
        if part.split("[", 1)[0].endswith(segment_name):
            return tuple(int(m) for m in _BRACKET_INDEX_RE.findall(part))
    raise ValueError(
        f"Segment ending in {segment_name!r} not found in tcname {tcname!r}"
    )


def _find_symbol_by_suffix(tmc, symbol_class, name_suffix):
    """Find the unique symbol whose name ends with ``name_suffix``."""
    matches = [s for s in tmc.find(symbol_class) if s.name.endswith(name_suffix)]
    if not matches:
        pytest.skip(
            f"TMC fixture does not export a {symbol_class.__name__} ending "
            f"in {name_suffix!r}"
        )
    if len(matches) > 1:
        raise AssertionError(
            f"Multiple {symbol_class.__name__} symbols end in {name_suffix!r}: "
            f"{[s.name for s in matches]}"
        )
    return matches[0]


# Maps each per-device afbMotorsNCDx array to the expected
# (PV prefix, {array index: (expand-name, axis-link)}) pairs from PRG.TcPOU.
_AFB_MOTORS_DEVICES = {
    "afbMotorsNCD1": (
        "TST:D1",
        {
            1: ("D1M1", "GVL_Axes.Axes[1]"),
            2: ("D1M2", "GVL_Axes.Axes[2]"),
            3: ("D1M3", "GVL_Axes.Axes[3]"),
            4: ("D1M4", "GVL_Axes.Axes[4]"),
        },
    ),
    "afbMotorsNCD2": (
        "TST:D2",
        {
            1: ("D2M1", "GVL_Axes.Axes[5]"),
            2: ("D2M2", "GVL_Axes.Axes[6]"),
            3: ("D2M3", "GVL_Axes.Axes[7]"),
        },
    ),
    "afbMotorsNCD3": (
        "TST:D3",
        {
            1: ("D3M1", "GVL_Axes.Axes[8]"),
            2: ("D3M2", "GVL_Axes.Axes[9]"),
        },
    ),
}


@pytest.mark.parametrize("suffix", sorted(_AFB_MOTORS_DEVICES))
def test_real_tmc_afbMotorsNC_expand_names_and_axis_link(real_tmc, suffix):
    """1D ARRAY OF FB_MotionStageNC with expand-names + explicit axis-link.

    The PRG fixture declares three state-mover devices (D1: 4 motors,
    D2: 3 motors, D3: 2 motors), e.g.:

        afbMotorsNCD1 : ARRAY[1..4] OF FB_MotionStageNC[
            (AxisRef := GVL_Axes.Axes[1], ...),
            ...
        ];

        with pragma:
            pv: TST:D1
            io: io
            array: 1..4
            axis-link: GVL_Axes.Axes[1..4]
            expand-names: D1M1, D1M2, D1M3, D1M4

    Per device, verifies:

    1. expand-names produces role-named PV suffixes per array element
       under the device's PV prefix.
    2. The explicit-list axis-link form lands the right axis reference
       on each array element's proxy as ``axis_link_override``, so that
       Symbol_FB_MotionStage.get_axis_link() returns the per-element
       value instead of re-reading the array-level pragma.
    """
    pv_prefix, expected = _AFB_MOTORS_DEVICES[suffix]
    afb = _find_symbol_by_suffix(
        real_tmc, parser.Symbol_FB_MotionStage, suffix
    )

    chains = list(pragmas.chains_from_symbol(afb))
    assert chains, f"No chains produced for {suffix}"

    # Group chains by array index extracted from tcname.
    chains_by_index = {}
    for c in chains:
        (idx,) = _extract_indices_for_segment(c.tcname, suffix)
        chains_by_index.setdefault(idx, []).append(c)

    assert set(chains_by_index) == set(expected), (
        f"{suffix}: expected array indices {sorted(expected)}, got "
        f"{sorted(chains_by_index)}"
    )

    expected_prefix_segments = pv_prefix.split(":")

    # Per-element checks.
    for idx, (role, axis_link) in expected.items():
        element_chains = chains_by_index[idx]

        # 1. Every chain for this element carries the role name as the
        #    segment after the device prefix: <pv_prefix>:<role>:<rest>
        for c in element_chains:
            segments = c.pvname.split(":")
            assert (
                segments[: len(expected_prefix_segments) + 1]
                == expected_prefix_segments + [role]
            ), (
                f"{suffix}[{idx}] chain pvname={c.pvname!r} does not start "
                f"with {pv_prefix}:{role}:..."
            )

        # 2. The first chain item is the array element proxy. Its
        #    axis_link_override must match the expected axis link.
        sample = element_chains[0]
        proxy = sample.chain[0]
        override = proxy.__dict__.get("axis_link_override")
        assert override == axis_link, (
            f"{suffix}[{idx}] axis_link_override={override!r}, "
            f"expected {axis_link!r}"
        )

        # 3. The proxy's get_axis_link(), the production accessor,
        #    must return the same value, proving the override is wired
        #    into Symbol_FB_MotionStage.get_axis_link() correctly.
        assert proxy.get_axis_link() == axis_link, (
            f"{suffix}[{idx}] get_axis_link()={proxy.get_axis_link()!r}, "
            f"expected {axis_link!r}"
        )


# Maps each per-device astPositionStateDx 2D array to its
# (PV prefix, outer expand-names, inner count) from PRG.TcPOU.
_AST_POSITION_STATE_DEVICES = {
    "astPositionStateD1": (
        "TST:D1:STATE",
        ("D1M1", "D1M2", "D1M3", "D1M4"),
        4,
    ),
    "astPositionStateD2": (
        "TST:D2:STATE",
        ("D2M1", "D2M2", "D2M3"),
        3,
    ),
    "astPositionStateD3": (
        "TST:D3:STATE",
        ("D3M1", "D3M2"),
        2,
    ),
}


@pytest.mark.parametrize("suffix", sorted(_AST_POSITION_STATE_DEVICES))
def test_real_tmc_astPositionState_2d_expand_names(real_tmc, suffix):
    """2D ARRAY OF ST_PositionState with expand-names on the outer dim.

    The PRG fixture declares one 2D state table per device, with the
    sliced size matching the device's motor count, e.g.:

        astPositionStateD1 : ARRAY[1..4] OF ARRAY[1..4]
                             OF ST_PositionState;

        with pragma:
            pv: TST:D1:STATE
            io: io
            array: 1..4 | 1..4
            expand-names: D1M1, D1M2, D1M3, D1M4

    ST_PositionState has pragma'd subitems (NAME, SETPOINT, ENCODER,
    MOVE_OK), so each leaf cell expands to multiple PVs. Per device,
    verifies:

    1. All N (outer) x N (inner) leaf cells appear with the expected
       role-name x numeric prefix (N = device's motor count).
    2. The pragma'd subitems propagate under each cell.

    expand-names applies only to the outer dimension; the inner
    dimension uses the numeric default (`:01`, `:02`, ...).
    """
    symbol_class = parser.TWINCAT_TYPES.get("Symbol_ST_PositionState")
    if symbol_class is None:
        pytest.skip(
            "Symbol_ST_PositionState not registered, TMC fixture missing "
            "an ST_PositionState symbol"
        )
    pv_prefix, roles, inner_count = _AST_POSITION_STATE_DEVICES[suffix]
    sym = _find_symbol_by_suffix(real_tmc, symbol_class, suffix)

    chains = list(pragmas.chains_from_symbol(sym))
    assert chains, f"No chains produced for {suffix}"
    pvnames = {c.pvname for c in chains}

    # 1. Every (outer, inner) cell produces at least one PV under the
    #    expected prefix.
    expected_cells = {
        f"{pv_prefix}:{role}:{inner:02d}"
        for role in roles
        for inner in range(1, inner_count + 1)
    }
    assert len(expected_cells) == len(roles) * inner_count

    for cell_prefix in expected_cells:
        cell_pvs = {pv for pv in pvnames if pv.startswith(cell_prefix + ":")}
        assert cell_pvs, (
            f"{suffix}: no PVs found under cell {cell_prefix!r}. "
            f"Sample of pvnames: {sorted(pvnames)[:6]}"
        )

    # 2. ST_PositionState's pragma'd subitems propagate under each
    #    cell. Sample the first cell and verify each subitem PV exists.
    sample_cell = f"{pv_prefix}:{roles[0]}:01"
    expected_subitem_pvs = {
        f"{sample_cell}:NAME",
        f"{sample_cell}:SETPOINT",
        f"{sample_cell}:ENCODER",
        f"{sample_cell}:MOVE_OK",
    }
    missing = expected_subitem_pvs - pvnames
    assert not missing, (
        f"{suffix}: missing subitem PVs under {sample_cell!r}: "
        f"{sorted(missing)}. Present under cell: "
        f"{sorted(pv for pv in pvnames if pv.startswith(sample_cell))}"
    )


def _fake_stage(name, low, high, pragma):
    """Build the minimal stage surface `_expand_motor_array` reads.

    Mirrors the attributes the function actually touches: ``name``,
    ``array_dimensions``, and ``Properties[0].Property[].(name,value)``
    used by ``parser.get_pragma``.
    """
    prop = types.SimpleNamespace(name="pytmc", value=pragma)
    properties = types.SimpleNamespace(Property=[prop])
    return types.SimpleNamespace(
        name=name,
        array_dimensions=[(low, high)],
        Properties=[properties],
    )


def test_expand_motor_array_honors_array_subset():
    """`_expand_motor_array` only yields proxies for the array: slice.

    With ``array: 1,3`` on a 1..4 array, only two proxies are emitted
    and their pvnames + axis_link_overrides come from the
    (slice-sized) expand-names and axis-link lists positionally.
    """
    stage = _fake_stage(
        "Main.motors", 1, 4,
        "pv: TST:MAL\n"
        "expand-names: MMS, CLF\n"
        "axis-link: GVL.A[5], GVL.A[7]\n"
        "array: 1,3"
    )
    proxies = list(template._expand_motor_array(stage))

    assert [p.name for p in proxies] == [
        "Main.motors[1]",
        "Main.motors[3]",
    ]
    assert [p.__dict__["pvname_override"] for p in proxies] == [
        "TST:MAL:MMS",
        "TST:MAL:CLF",
    ]
    assert [p.__dict__["axis_link_override"] for p in proxies] == [
        "GVL.A[5]",
        "GVL.A[7]",
    ]


def test_expand_motor_array_subset_axis_link_length_mismatch_raises():
    """axis-link explicit list must match the array: slice count."""
    stage = _fake_stage(
        "Main.motors", 1, 4,
        "pv: TST:MAL\n"
        "expand-names: MMS, CLF\n"
        "axis-link: GVL.A[5], GVL.A[6], GVL.A[7], GVL.A[8]\n"
        "array: 1,3"
    )
    with pytest.raises(RuntimeError, match="the array: slice requires 2"):
        list(template._expand_motor_array(stage))


def test_expand_motor_array_subset_expand_names_length_mismatch_raises():
    """expand-names must also validate against the slice when array: set."""
    stage = _fake_stage(
        "Main.motors", 1, 4,
        "pv: TST:MAL\n"
        "expand-names: MMS, CLZ, CLF, YAG\n"
        "axis-link: GVL.A[5], GVL.A[7]\n"
        "array: 1,3"
    )
    with pytest.raises(ValueError, match="the array: slice"):
        list(template._expand_motor_array(stage))


def test_expand_motor_array_rejects_multi_dim_array_selector():
    """`|`-separated array: is only meaningful on multi-dim arrays.

    Motion FBs are 1D-only here (mirrors handle_array_complex's
    axis-link rejection of multi-dim arrays), so any `|` in the
    selector is a config error.
    """
    stage = _fake_stage(
        "Main.motors", 1, 4,
        "pv: TST:MAL\n"
        "expand-names: MMS, CLF\n"
        "axis-link: GVL.A[5], GVL.A[7]\n"
        "array: 1,3 | 1..2"
    )
    with pytest.raises(RuntimeError, match="Multi-dimensional array:"):
        list(template._expand_motor_array(stage))


def test_expand_motor_array_no_array_pragma_back_compat():
    """Without `array:`, full bounds are iterated as before."""
    stage = _fake_stage(
        "Main.motors", 1, 3,
        "pv: TST:MAL\n"
        "expand-names: MMS, CLZ, CLF\n"
        "axis-link: GVL.A[%d]"
    )
    proxies = list(template._expand_motor_array(stage))

    assert [p.name for p in proxies] == [
        "Main.motors[1]",
        "Main.motors[2]",
        "Main.motors[3]",
    ]
    assert [p.__dict__["axis_link_override"] for p in proxies] == [
        "GVL.A[1]",
        "GVL.A[2]",
        "GVL.A[3]",
    ]
